<x-filament-panels::page>
    <style>
        body:has(.lde-root) .fi-sidebar,body:has(.lde-root) .fi-topbar{display:none!important}body:has(.lde-root) .fi-main{margin:0!important;padding:0!important;max-width:none!important}body:has(.lde-root) .fi-page{padding:0!important;max-width:none!important}.lde-root{height:100vh;overflow:hidden;background:#020617;color:#e5eefc;display:grid;grid-template-rows:auto 1fr}.lde-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;border-bottom:1px solid rgba(255,255,255,.08);background:rgba(2,6,23,.96)}.lde-left,.lde-actions{display:flex;align-items:center;gap:9px}.lde-back,.lde-btn{border:1px solid rgba(255,255,255,.12);border-radius:11px;padding:9px 12px;background:rgba(255,255,255,.05);color:#fff;font-size:10.5px;font-weight:900;text-decoration:none;cursor:pointer}.lde-btn.primary{border-color:transparent;background:linear-gradient(135deg,#0891b2,#7c3aed)}.lde-title h1{margin:0;color:#fff;font-size:16px}.lde-title p{margin:3px 0 0;color:rgba(226,232,240,.55);font-size:9.5px}.lde-state{padding:6px 9px;border-radius:999px;background:rgba(244,63,94,.09);border:1px solid rgba(244,63,94,.2);color:#fda4af;font-size:9px;font-weight:900}.lde-state.live{background:rgba(34,197,94,.09);border-color:rgba(34,197,94,.2);color:#86efac}.lde-body{display:grid;grid-template-columns:minmax(520px,1fr) minmax(420px,.9fr);gap:1px;min-height:0;background:rgba(255,255,255,.08)}.lde-editor,.lde-preview{min-height:0;background:#030817;overflow:hidden}.lde-editor{display:grid;grid-template-rows:auto 1fr}.lde-tabs{display:flex;gap:7px;overflow-x:auto;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08);background:rgba(3,8,20,.98)}.lde-tab{flex:0 0 auto;border:1px solid rgba(255,255,255,.1);border-radius:999px;padding:8px 11px;background:rgba(255,255,255,.04);color:rgba(226,232,240,.66);font-size:10px;font-weight:900;cursor:pointer}.lde-tab.active{color:#fff;border-color:rgba(34,211,238,.38);background:linear-gradient(135deg,rgba(8,145,178,.28